        brclr   <IPL2,#$03,StoreKnockVoltsAvgCounter
        bset    <IPL2,#$03

;---------------------------------------------------------------------------------------------------
; StoreKnockVoltsAvgCounter  ($AB68)
;---------------------------------------------------------------------------------------------------
StoreKnockVoltsAvgCounter:
        stab    <Counter_KnockVoltsAvg
        addb    <Temp0
        brset   <BitFlags65,#$80,CheckAndSetMinSparkAdvance ; throttle open (off idle)
        ldaa    <VehicleSpeed_HB
        bne     CheckAndSetMinSparkAdvance
        ldaa    <CoolantTemp
        cmpa    >LB9D2
        bls     CheckAndSetMinSparkAdvance
        ldaa    >Var_020D
        aba
        tab
        bra     LAB85


;---------------------------------------------------------------------------------------------------
; CheckAndSetMinSparkAdvance  ($AB82)
;---------------------------------------------------------------------------------------------------
CheckAndSetMinSparkAdvance:
        clr     >Var_020D
LAB85:
        bvc     LAB90
        tstb
        bpl     LAB8E
        ldab    #$7F
        bra     LAB90

LAB8E:
        ldab    #$80
LAB90:
        stab    <CalculatedSparkAdvance
        rts


;---------------------------------------------------------------------------------------------------
; IncrementDeltaRPMCounter_SM  ($AB93)
;
; Counts Counter_DeltaEngineRPM_1 up (saturating) while the throttle is closed. [reviewed]
;
; Called from: SubLoopB
;---------------------------------------------------------------------------------------------------
IncrementDeltaRPMCounter_SM:
        brset   <BitFlags65,#$80,LABA0               ; throttle open (off idle)
        ldaa    >Counter_DeltaEngineRPM_1
        inca
        beq     LABA0
        staa    >Counter_DeltaEngineRPM_1
LABA0:
        rts


;---------------------------------------------------------------------------------------------------
; HandleSparkScatter  ($ABA1)
;
; Entry of the idle spark scatter (spark used to hold idle speed). [reviewed]
;
; Skipped while the engine is not running or the throttle is open. In the basic-timing DRB mode it
; uses the constant SPKSET. Otherwise, once the AIS feedback delay is over and BitFlags66 bit 6 is
; set, it calculates the scatter unless IPL1 bits 7 or 5 are set.
;
; Called from: CrankInterrupt_FallingEdge
;---------------------------------------------------------------------------------------------------
HandleSparkScatter:
        ldaa    <BitFlags71
        oraa    <BitFlags65
        bmi     LABBE
        brset   <BitFlags6b,#$20,LABAF
        brclr   <b58_IPL1,#$02,LABB6
LABAF:
        ldab    >SPKSET_ConstantSparkAdvanceWhenSettingBasicTiming ; SPKSET: Constant spark advance setting when setting basic timing (stock 12 deg
        stab    <Temp5
        bra     LABBE

LABB6:
        ldaa    <Timer_CountdownFromStartRunForAisFeedback
        bne     LABBE
        brclr   <BitFlags66,#$40,LABBF
LABBE:
        rts

LABBF:
        brclr   <b58_IPL1,#$A0,CalculateSparkScatter
        bra     LAC17


;---------------------------------------------------------------------------------------------------
; CalculateSparkScatter  ($ABC5)
;---------------------------------------------------------------------------------------------------
CalculateSparkScatter:
        ldab    <CoolantTemp
        cmpb    >SSTEMP_TempAboveWhichSparkScatterIsActive ; SSTEMP: Temperature above which spark scatter is active. For road racing, the
        bls     LAC17
        ldx     <KeyOnOrEngineRunningTime
        cpx     >SSITIM_ScatterInhibitTime           ; SSITIM: Spark Scatter Inhibit Time in 11ms per bit
        bcs     LAC17
        ldx     <TimerOverflowsBetweenCamPulses
        cpx     >SSIPRD_ScatterInhibitBelowThisSpeed ; SSIPRD: Spark Scatter inhibited below this speed. The MP MTX cal has this valu
        bcc     LAC17
        brset   <BitFlags6a,#$02,LAC17
        ldaa    >EngineIdleIncrDecrBit7
        bpl     LAC03
        ldx     #SPKRET_SparkAdvanceRetardedWhenRpmAboveControl_FromDeltaRpm ; SPKRET: This is how much advance is added to increase engine speed.
        brset   <BitFlags_AIS,#$08,LABED
        ldx     #SPKRT2_SparkAdvanceRetardedWhenRpmAboveControl2_FromDeltaRpm ; SPKRT2: This is how much advance is added to increase engine speed.
LABED:
        jsr     >Lookup4ByteTable                    ; 2D table lookup with linear interpolation ("point-slope" format).
        staa    >SparkScatter
        ldaa    <CalculatedSparkAdvance
        sba
        bvc     LAC01
        tsta
        bpl     LABFF
        ldaa    #$7F
        bra     LAC01

LABFF:
        ldaa    #$80
LAC01:
        bra     LAC15

LAC03:
        ldx     #SPKADD_SparkAdvanceAddedWhenRpmBelowControl_FromDeltaRpm ; SPKADD: This is how much advance is added to increase engine speed.
        brset   <BitFlags_AIS,#$08,LAC0D
        ldx     #SPKAD2_SparkAdvanceAddedWhenRpmBelowControl2_FromDeltaRpm ; SPKAD2: This is how much advance is added to increase engine speed.
LAC0D:
        jsr     >Lookup4ByteTable                    ; 2D table lookup with linear interpolation ("point-slope" format).
        staa    >SparkScatter
        adda    <CalculatedSparkAdvance
LAC15:
        staa    <Temp5
LAC17:
        brclr   <BitFlags6b,#$10,LAC20
        ldab    >IDLSET_ConstantSparkAdvanceWhenSettingMinThrottleOpening ; IDLSET: Constant spark advance setting when setting min throttle blade opening
        stab    <Temp5
LAC20:
        rts
